CREATE TRIGGER RefComplianceCommodityAlert_Version_Update
	ON RefComplianceCommodityAlert
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RCR_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
